<?php
require_once "../config/koneksi.php";require_once "../config/auth.php";require_role('admin');$title="Data Kriteria";
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$aksi=$_POST['aksi']??'';if($aksi==='hapus'){$pdo->prepare("DELETE FROM kriteria WHERE id=?")->execute([(int)($_POST['id']??0)]);}else{$id=(int)($_POST['id']??0);$kode=trim($_POST['kode']);$nama=trim($_POST['nama']);$bobot=(float)$_POST['bobot'];if($id)$pdo->prepare("UPDATE kriteria SET kode=?,nama=?,bobot=?,atribut='benefit' WHERE id=?")->execute([$kode,$nama,$bobot,$id]);else$pdo->prepare("INSERT INTO kriteria(kode,nama,bobot,atribut) VALUES(?,?,?,'benefit')")->execute([$kode,$nama,$bobot]);}header("Location:index.php");exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM kriteria WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query("SELECT * FROM kriteria ORDER BY kode")->fetchAll();$total=array_sum(array_column($rows,'bobot'));include "../layout/header.php";?>
<div class="d-flex justify-content-between mb-3"><h3>Data Kriteria</h3><a class="btn btn-primary" href="?tambah=1">+ Tambah</a></div>
<div class="alert <?=$total==1?'alert-success':'alert-warning'?>">Total bobot: <b><?=number_format($total,2)?></b>. <?=count($rows)===6?'(100%).':'Jumlah kriteria harus 6.'?></div>
<?php if(isset($_GET['tambah'])||$edit):?><div class="card mb-3"><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="aksi" value="simpan"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="row g-2"><div class="col-md-2"><input class="form-control" name="kode" placeholder="C1" required value="<?=e($edit['kode']??'')?>"></div><div class="col-md-5"><input class="form-control" name="nama" placeholder="Nama kriteria" required value="<?=e($edit['nama']??'')?>"></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" min="0" max="1" name="bobot" placeholder="Bobot" required value="<?=e($edit['bobot']??'')?>"></div><div class="col-md-3"><button class="btn btn-success">Simpan</button> <a class="btn btn-secondary" href="index.php">Batal</a></div></div></form></div></div><?php endif;?>
<div class="card"><div class="card-body table-responsive"><table class="table table-bordered"><tr><th>No</th><th>Kode</th><th>Kriteria</th><th>Bobot</th><th>Atribut</th><th>Aksi</th></tr><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['kode'])?></td><td><?=e($r['nama'])?></td><td><?=number_format($r['bobot'],2)?> <span class="text-muted">(<?=number_format($r['bobot']*100,0)?>%)</span></td><td>Benefit</td><td><a class="btn btn-sm btn-warning" href="?edit=<?=$r['id']?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Hapus?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-danger">Hapus</button></form></td></tr><?php endforeach;?></table></div></div><?php include "../layout/footer.php";?>
